* { box-sizing: border-box; }
:root { color-scheme: light; --ink: #24223b; --muted: #77758a; --paper: #fffdf6; --lavender: #e9e4ff; --purple: #6554c0; --mint: #bfe9d4; }
body { margin: 0; min-height: 100vh; padding: 32px 16px; display: grid; place-items: center; background-color: #d9d4f3; background-image: radial-gradient(#b7afe3 1.5px, transparent 1.5px); background-size: 18px 18px; color: var(--ink); font: 16px/1.5 system-ui, sans-serif; }
.card { width: min(100%, 520px); padding: 32px; background: var(--paper); border: 3px solid var(--ink); box-shadow: 8px 8px 0 var(--ink); }
.header { text-align: center; }
.pixel-clock { width: 56px; height: 56px; margin: 0 auto 14px; display: grid; place-items: center; border: 3px solid var(--ink); background: var(--mint); font-size: 34px; line-height: 1; box-shadow: 4px 4px 0 var(--ink); }
.eyebrow, .summary-label, footer { font-size: 12px; font-weight: 800; letter-spacing: .13em; }
.eyebrow { margin: 0 0 3px; color: var(--purple); }
h1 { margin: 0; font-size: clamp(27px, 7vw, 36px); line-height: 1.2; letter-spacing: -.04em; }
.intro { margin: 8px 0 24px; color: var(--muted); }
.summary { min-height: 64px; margin-bottom: 24px; padding: 12px 16px; display: flex; align-items: center; justify-content: space-between; border: 2px solid var(--ink); background: var(--lavender); }
.summary-label { color: var(--purple); }
.summary strong { font-size: 26px; line-height: 1; }
fieldset { min-width: 0; margin: 0; padding: 0; border: 0; }
legend { margin-bottom: 12px; font-size: 19px; font-weight: 800; }
.time-fields { display: flex; align-items: end; gap: 12px; }
.time-fields label, .label-field { display: grid; gap: 6px; font-weight: 700; }
.time-fields input { width: 100%; min-width: 0; text-align: center; font-variant-numeric: tabular-nums; }
.time-fields label { flex: 1; }
.time-colon { padding-bottom: 9px; font-size: 24px; font-weight: 800; }
input { min-height: 48px; padding: 10px 12px; border: 2px solid #c9c5d9; border-radius: 0; background: #fff; color: var(--ink); font: inherit; }
input:focus-visible, button:focus-visible { outline: 3px solid var(--purple); outline-offset: 3px; }
.label-field { margin-top: 14px; }
.label-field span { color: var(--muted); font-weight: 400; }
.add-button { width: 100%; min-height: 50px; margin-top: 18px; border: 2px solid var(--ink); background: var(--purple); color: #fff; font: inherit; font-weight: 800; cursor: pointer; box-shadow: 3px 3px 0 var(--ink); transition: transform .12s, box-shadow .12s, background .12s; }
.add-button:hover { background: #5141aa; }
button:active { transform: translate(2px, 2px); box-shadow: 1px 1px 0 var(--ink); }
.alarm-section { margin-top: 30px; }
.list-heading { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; padding-bottom: 10px; border-bottom: 2px solid var(--ink); }
h2 { margin: 0; font-size: 20px; }
.sort-note { color: var(--muted); font-size: 13px; }
.alarm-list { display: grid; gap: 10px; margin: 14px 0 0; padding: 0; list-style: none; }
.alarm-item { min-height: 74px; padding: 12px; display: flex; align-items: center; gap: 10px; border: 2px solid var(--ink); background: #fff; }
.alarm-item.off { background: #f0eef5; color: var(--muted); }
.alarm-time { flex: 0 0 auto; font-size: 25px; font-weight: 800; font-variant-numeric: tabular-nums; letter-spacing: .02em; }
.alarm-info { min-width: 0; flex: 1; }
.alarm-name { overflow: hidden; color: var(--muted); font-size: 14px; text-overflow: ellipsis; white-space: nowrap; }
.toggle-label { display: flex; align-items: center; gap: 6px; font-size: 13px; font-weight: 700; cursor: pointer; }
.toggle-label input { width: 20px; min-height: 20px; height: 20px; margin: 0; accent-color: var(--purple); }
.delete-button { width: 40px; height: 40px; border: 2px solid transparent; background: transparent; color: var(--ink); font: inherit; font-size: 22px; cursor: pointer; }
.delete-button:hover { border-color: var(--ink); background: var(--lavender); }
.empty-state { margin: 16px 0 0; padding: 18px 12px; border: 2px dashed #c9c5d9; color: var(--muted); text-align: center; }
footer { margin-top: 28px; color: var(--muted); text-align: center; }
footer span { color: var(--purple); }
@media (max-width: 420px) { body { padding: 18px 12px; } .card { padding: 24px 18px; box-shadow: 6px 6px 0 var(--ink); } .alarm-item { gap: 6px; padding: 9px 7px; } .alarm-time { font-size: 22px; } .toggle-label { gap: 4px; font-size: 12px; } .delete-button { width: 34px; } }

const form = document.querySelector('#alarm-form');
const hourInput = document.querySelector('#alarm-hour');
const minuteInput = document.querySelector('#alarm-minute');
const labelInput = document.querySelector('#alarm-label');
const list = document.querySelector('#alarm-list');
const count = document.querySelector('#enabled-count');
const emptyState = document.querySelector('#empty-state');
let alarms = [];
let nextId = 1;

function render() {
  const sorted = [...alarms].sort((a, b) => a.hour * 60 + a.minute - (b.hour * 60 + b.minute));
  list.replaceChildren();
  sorted.forEach(alarm => {
    const item = document.createElement('li');
    item.className = `alarm-item${alarm.enabled ? '' : ' off'}`;
    const time = document.createElement('strong');
    time.className = 'alarm-time';
    time.textContent = `${String(alarm.hour).padStart(2, '0')}:${String(alarm.minute).padStart(2, '0')}`;
    const info = document.createElement('div');
    info.className = 'alarm-info';
    const name = document.createElement('div');
    name.className = 'alarm-name';
    name.textContent = alarm.label || 'Alarm';
    info.append(name);
    const toggleLabel = document.createElement('label');
    toggleLabel.className = 'toggle-label';
    const toggle = document.createElement('input');
    toggle.type = 'checkbox';
    toggle.checked = alarm.enabled;
    toggle.setAttribute('aria-label', `Alarm ${time.textContent}${alarm.label ? `, ${alarm.label}` : ''} on`);
    toggle.addEventListener('change', () => {
      alarm.enabled = toggle.checked;
      render();
    });
    toggleLabel.append(toggle, document.createTextNode('On'));
    const remove = document.createElement('button');
    remove.type = 'button';
    remove.className = 'delete-button';
    remove.textContent = '×';
    remove.setAttribute('aria-label', `Delete alarm ${time.textContent}${alarm.label ? `, ${alarm.label}` : ''}`);
    remove.addEventListener('click', () => {
      alarms = alarms.filter(entry => entry.id !== alarm.id);
      render();
    });
    item.append(time, info, toggleLabel, remove);
    list.append(item);
  });
  count.textContent = alarms.filter(alarm => alarm.enabled).length;
  emptyState.hidden = alarms.length > 0;
}

form.addEventListener('submit', event => {
  event.preventDefault();
  const hour = Number(hourInput.value);
  const minute = Number(minuteInput.value);
  if (!Number.isInteger(hour) || hour < 0 || hour > 23 || !Number.isInteger(minute) || minute < 0 || minute > 59) return;
  alarms.push({ id: nextId++, hour, minute, label: labelInput.value.trim(), enabled: true });
  form.reset();
  hourInput.focus();
  render();
});

render();
